import numpy as np


def softplus(x):
    x = np.asarray(x, dtype=np.float64)
    return np.maximum(x, 0.0) + np.log1p(np.exp(-np.abs(x)))


def conservative_dpo_loss(margin, beta, label_smoothing):
    eps = float(label_smoothing)
    if beta <= 0 or not 0 <= eps < 0.5:
        raise ValueError("invalid beta or smoothing")
    z = beta * np.asarray(margin, dtype=np.float64)
    return (1.0 - eps) * softplus(-z) + eps * softplus(z)


def ipo_loss(margin, tau):
    if tau <= 0:
        raise ValueError("tau must be positive")
    margin = np.asarray(margin, dtype=np.float64)
    return (margin - 1.0 / (2.0 * tau)) ** 2
```

