import math


def softplus(x):
    return max(x, 0.0) + math.log1p(math.exp(-abs(x)))


def simpo_reward(sequence_logp, length, beta):
    if length <= 0 or beta <= 0:
        raise ValueError("positive length and beta required")
    return beta * sequence_logp / length


def log_odds_from_logprob(logp):
    if not math.isfinite(logp) or logp >= 0:
        raise ValueError("logp must be finite and negative")
    p = math.exp(logp)
    return logp - math.log1p(-p)


def orpo_total_loss(chosen_mean_nll, chosen_logp, rejected_logp, lam):
    if chosen_mean_nll < 0 or lam < 0:
        raise ValueError("non-negative inputs required")
    ratio = log_odds_from_logprob(chosen_logp) - log_odds_from_logprob(rejected_logp)
    return chosen_mean_nll + lam * softplus(-ratio)
